def logger(func):
    def wrapper(name):
        print("start")
        func(name)
        print("end")
    return wrapper


@logger
def greet(name):
    print(f"Hello, {name}")


who = input()
greet(who)

def louden(func):
    def wrapper(msg):
        return func(msg).upper()
    return wrapper


@louden
def shout(msg):
    return "notice: " + msg


msg = input()
print(shout(msg))

def count_up(limit):
    value = 1
    while value <= limit:
        yield value
        value += 1


n = int(input())
for number in count_up(n):
    print(number)

def evens_only(values):
    for v in values:
        if v % 2 == 0:
            yield v


n = int(input())
values = [int(x) for x in input().split()]
for even in evens_only(values):
