def countdown(start):
    while start >= 1:
        yield start
        start -= 1


n = int(input())
for tick in countdown(n):
    print(tick)

def step_counter(func):
    calls = 0

    def wrapper(value):
        nonlocal calls
        calls += 1
        print(f"call {calls}")
        return func(value)

    return wrapper


@step_counter
def double(value):
    print(value * 2)


n = int(input())
values = [int(x) for x in input().split()]
for v in values:
    double(v)

def rate_limiter(limit):
    def deco(func):
        granted = 0

        def wrapper(tag):
            nonlocal granted
            if granted < limit:
                granted += 1
                print("allowed")
                return func(tag)
            print("blocked")
            return None

        return wrapper

    return deco


limit = int(input())


@rate_limiter(limit)
def ping(tag):
    return f"pong {tag}"


n = int(input())
for _ in range(n):
    result = ping(input())
    if result is not None:
        print(result)

def batches(values, size):
    batch = []
    for v in values:
        batch.append(v)
        if len(batch) == size:
            yield batch
            batch = []
    if batch:
        yield batch


n, k = map(int, input().split())
values = [int(x) for x in input().split()]
for chunk in batches(values, k):
    print(*chunk)

def fibonacci(count):
    a, b = 1, 1
    for _ in range(count):
        yield a
        a, b = b, a + b


n = int(input())
for term in fibonacci(n):
    print(term)

def repeat(times):
    def deco(func):
        def wrapper(msg):
            for _ in range(times):
                print(func(msg))
        return wrapper

    return deco


k = int(input())


@repeat(k)
def announce(msg):
    return f"Announcing: {msg}"


n = int(input())
for _ in range(n):
    announce(input())

def memo(func):
    cache = {}

    def wrapper(k):
        if k not in cache:
            cache[k] = func(k)
        return cache[k]

    return wrapper


@memo
def growth(k):
    if k <= 2:
        return 1
    return growth(k - 1) + growth(k - 2)


q = int(input())
for _ in range(q):
    print(growth(int(input())))

def read_ticks(count):
    for _ in range(count):
        yield int(input())


def above(stream, threshold):
    for tick in stream:
        if tick > threshold:
            yield tick


def scale(stream, factor):
    for tick in stream:
        yield tick * factor


n, threshold, factor = map(int, input().split())
pipeline = scale(above(read_ticks(n), threshold), factor)
for value in pipeline:
    print(value)

