def audit(func):
    def wrapper(amount):
        print(f"audit-before {amount}")
        result = func(amount)
        print(f"audit-after {result}")
        return result

    return wrapper


def prefix(func):
    def wrapper(amount):
        print("prefix-before")
        result = func(amount)
        print("prefix-after")
        return ">> " + str(result)

    return wrapper


@audit
@prefix
def charge(amount):
    return amount * 2


n = int(input())
for _ in range(n):
    final = charge(int(input()))
    print(f"FINAL {final}")

class FlakyError(Exception):
    pass


def retry(limit):
    def deco(func):
        def wrapper():
            for attempt in range(1, limit + 1):
                print(f"attempt {attempt}")
                try:
                    func(attempt)
                    print(f"success on attempt {attempt}")
                    return "OK"
                except FlakyError:
                    print("failed")
            print("job aborted")
            return None

        return wrapper

    return deco


limit = int(input())
schedule = input().split()


@retry(limit)
def run_job(attempt):
    ok = attempt <= len(schedule) and schedule[attempt - 1] == "1"
    if not ok:
        raise FlakyError("flaky")


outcome = run_job()
if outcome == "OK":
    print("job done")

def record_stream(count):
    for _ in range(count):
        sku, qty = input().split()
        yield (sku, int(qty))


def paginate(source, size):
    page = []
    for rec in source:
        page.append(rec)
        if len(page) == size:
            yield page
            page = []
    if page:
        yield page


k, n = map(int, input().split())
for page_no, page in enumerate(paginate(record_stream(n), k), 1):
    noun = "record" if len(page) == 1 else "records"
    print(f"PAGE {page_no} ({len(page)} {noun})")
    for sku, qty in page:
        print(f"  {sku} {qty}")
